const ELEMENT_PROP_KEYS = new Set(["theme","hold","turn","fontWeight","accent","fontFamily","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  hold: 26,
  turn: 26,
  fontWeight: 500,
  fontFamily: "IBM Plex Sans",
  scale: 1,
  delay: 0,
  speed: 1,
};

type SpineTurnElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof SpineTurnBase>;

const SpineTurnInner = forwardRef<
  HTMLDivElement,
  SpineTurnElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<SpineTurn>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <SpineTurnBase
          {...(componentProps as unknown as ComponentProps<typeof SpineTurnBase>)}
        />
      </div>
    </Sequence>
  );
});

export const SpineTurn = Interactive.withSchema({
  Component: SpineTurnInner,
  componentName: "<SpineTurn>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
